mockup.css:
.mock-section-comparison-columns { background: #f7f5ee; color: #17150f; font-family: var(--f-sans);
  padding: 5cqw 6cqw; display: flex; flex-direction: column; gap: 2.6cqw; }
.mock-section-comparison-columns h4 { margin: 0; font-family: var(--f-serif); font-size: 3.4cqw; }
.mock-section-comparison-columns .g { display: grid; grid-template-columns: 1fr 22% 22%; }
.mock-section-comparison-columns .g > * { padding: 1.5cqw 0; border-top: 1px solid rgba(23,21,15,.16); font-size: 1.45cqw; }
.mock-section-comparison-columns .g > .hd { border-top: 0; font-weight: 600; font-size: 1.85cqw; padding-top: 0; }
.mock-section-comparison-columns .g .lb { opacity: .66; }
.mock-section-comparison-columns .g .v { font-family: var(--f-mono); font-size: 1.4cqw; }
